Convert this Oracle DDL to PostgreSQL 16 compatible SQL. Use GENERATED ALWAYS AS IDENTITY for the primary key. Replace all Oracle-specific types and syntax. Return SQL only, no explanations.

CREATE TABLE ORDERS (
  ID NUMBER(19) PRIMARY KEY,
  ORDER_NO VARCHAR2(40) NOT NULL,
  AMOUNT NUMBER(15,2) DEFAULT 0 NOT NULL,
  CREATED_AT DATE DEFAULT SYSDATE,
  STATUS CHAR(1) DEFAULT 'A' NOT NULL,
  PAYLOAD CLOB
);
CREATE INDEX IX_ORDERS_CREATED_AT ON ORDERS(CREATED_AT);
CREATE INDEX IX_ORDERS_STATUS ON ORDERS(STATUS) WHERE STATUS != 'D';

Convert this Oracle procedure to PostgreSQL PL/pgSQL. Use FOUND instead of SQL%ROWCOUNT. Return only the function SQL, no explanations.

CREATE OR REPLACE PROCEDURE set_order_total(p_id IN NUMBER, p_total IN NUMBER) AS
BEGIN
  UPDATE orders SET amount = NVL(p_total, 0), created_at = SYSDATE WHERE id = p_id;
  IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO orders(id, order_no, amount, created_at) VALUES (p_id, 'NEW', NVL(p_total,0), SYSDATE);
  END IF;
END;
/

Convert this Oracle SEQUENCE and table to PostgreSQL 16. Use GENERATED ALWAYS AS IDENTITY — do NOT use a separate CREATE SEQUENCE. Return SQL only.

CREATE SEQUENCE orders_seq START WITH 1000 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE TABLE ORDERS (
  ID NUMBER(19) DEFAULT orders_seq.NEXTVAL PRIMARY KEY,
  ORDER_NO VARCHAR2(40) NOT NULL,
  AMOUNT NUMBER(15,2) DEFAULT 0 NOT NULL
);

Convert this Oracle trigger to PostgreSQL 16. PostgreSQL requires a separate trigger function returning TRIGGER. Use NEW.column := value syntax. Return SQL only.

CREATE OR REPLACE TRIGGER orders_audit_trg
BEFORE INSERT OR UPDATE ON orders
FOR EACH ROW
BEGIN
  :NEW.updated_at := SYSDATE;
  :NEW.updated_by := SYS_CONTEXT('USERENV','SESSION_USER');
END;
/

Convert this Oracle PL/SQL to PostgreSQL PL/pgSQL. Replace BULK COLLECT with an array or cursor loop. Replace FORALL with a FOR loop or set-based INSERT/DELETE. Replace %TYPE with concrete types. Return SQL only.

CREATE OR REPLACE PROCEDURE archive_old_orders(p_days IN NUMBER) AS
  TYPE t_ids IS TABLE OF orders.id%TYPE;
  v_ids t_ids;
BEGIN
  SELECT id BULK COLLECT INTO v_ids
  FROM orders
  WHERE created_at < SYSDATE - p_days;

  FORALL i IN 1..v_ids.COUNT
    INSERT INTO orders_archive SELECT * FROM orders WHERE id = v_ids(i);

  FORALL i IN 1..v_ids.COUNT
    DELETE FROM orders WHERE id = v_ids(i);
END;
/
